ROOT=Path(__file__).resolve().parents[1]; rep=ROOT/'reports'
main=pd.read_csv(rep/'main_results.csv'); pareto=pd.read_csv(rep/'pareto_comparison.csv'); profiles=pd.read_csv(rep/'profile_metrics.csv'); errors=pd.read_csv(rep/'error_analysis.csv'); audit=json.loads((rep/'data_audit.json').read_text(encoding='utf-8')); cold=json.loads((rep/'cold_start_validation.json').read_text(encoding='utf-8'))
nb=nbformat.v4.new_notebook(); nb.cells=[
 nbformat.v4.new_markdown_cell('# Ejercicio 05 · Motor recomendador reproducible\n\nEvidencia ejecutada de LAB08/LAB09. MovieLens permanece local; esta libreta resume los reportes reproducibles. Corte temporal por usuario, tres semillas (17, 42, 73).'),
 nbformat.v4.new_code_cell("from pathlib import Path\nimport pandas as pd, json\nroot=Path('..') if Path('../reports/main_results.csv').exists() else Path('.')\nr=root/'reports'\nresults=pd.read_csv(r/'main_results.csv'); pareto=pd.read_csv(r/'pareto_comparison.csv'); profiles=pd.read_csv(r/'profile_metrics.csv'); errors=pd.read_csv(r/'error_analysis.csv')\naudit=json.loads((r/'data_audit.json').read_text(encoding='utf-8')); cold=json.loads((r/'cold_start_validation.json').read_text(encoding='utf-8'))\nprint(f\"MovieLens: {audit['ratings']:,} valoraciones; {audit['movies']:,} películas; {audit['users']} usuarios\")\nprint(f\"Elegibles: {audit['eligible_test_events']}; excluidos por ítem/usuario sin entrenamiento: {audit['excluded_test_events']}\")\nprint('SHA-256 ZIP:',audit['sha256'])"),
 nbformat.v4.new_markdown_cell('## Resultados principales\n\nHitRate@10 usa un único evento futuro por usuario. Cobertura se calcula sobre el catálogo completo. RMSE aplica a la predicción de rating y no sustituye evaluación de ranking.'),
 nbformat.v4.new_code_cell("print(results.round(4).to_string(index=False))"),
 nbformat.v4.new_markdown_cell('## Perfiles y usuarios fríos\n\nHistorial corto: hasta el percentil 25 (34 ratings); amplio: desde el percentil 75 (167). La ruta de usuario frío no se puntúa con HitRate temporal porque no tiene historial evaluable.'),
 nbformat.v4.new_code_cell("print(profiles[(profiles.config=='20f_6e') & profiles.method.isin(['collaborative','hybrid_alpha_0.75'])].groupby(['method','profile'],as_index=False).agg(users=('users','first'),hit_rate=('hit_rate_at_10','mean'),coverage=('catalog_coverage','mean')).round(4).to_string(index=False))\nprint('Validación de fallbacks:',json.dumps(cold,ensure_ascii=False,indent=2))"),
 nbformat.v4.new_markdown_cell('## Comparación Pareto y decisión\n\nSe consideran utilidad (HitRate@10 y cobertura) y costo (tiempo de ajuste y parámetros). Las opciones no dominadas expresan compromisos distintos, no un ganador universal.'),
 nbformat.v4.new_code_cell("print(pareto.round(4).to_string(index=False))"),
 nbformat.v4.new_markdown_cell('## Auditoría de errores\n\nLa tabla de errores contiene los 587 usuarios elegibles para la configuración 8 factores/6 épocas, semilla 17, y registra título retenido, acierto y lista Top-5 para baseline, contenido, colaborativo e híbrido alpha=.75.'),
 nbformat.v4.new_code_cell("print('Filas:',len(errors),'| usuarios:',errors.userId.nunique(),'| aciertos:',int(errors.hit_at_10.sum()))\nprint(errors.groupby('method').hit_at_10.agg(['count','sum','mean']).round(4).to_string())\nprint(errors.head(8).to_string(index=False))"),
 nbformat.v4.new_markdown_cell('## Límites\n\nLos ratings son autoseleccionados y no miden satisfacción causal. Los metadatos de género son amplios, no hay demografía, y el corte temporal con un evento por usuario tiene alta varianza. Las tres semillas describen estabilidad de inicialización para esta muestra; no prueban significancia estadística ni generalización a producción.')]
nb.metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.12'}}
(ROOT/'notebooks').mkdir(exist_ok=True); ns={}
for i,c in enumerate(nb.cells,1):
 if c.cell_type=='code':
  out=io.StringIO()
  with contextlib.redirect_stdout(out): exec(c.source,ns)
  c.execution_count=i; c.outputs=[nbformat.v4.new_output('stream',name='stdout',text=out.getvalue())]
nbformat.write(nb,ROOT/'notebooks/ejercicio_05_motor_recomendador.ipynb')
styles=getSampleStyleSheet(); styles['BodyText'].fontSize=8.4; styles['BodyText'].leading=16.8; styles['BodyText'].alignment=TA_JUSTIFY; styles['BodyText'].spaceAfter=3; styles['Heading2'].fontSize=10.5; styles['Heading2'].leading=12; styles['Heading2'].spaceBefore=5; styles['Heading2'].spaceAfter=3
styles.add(ParagraphStyle(name='TitleCenter',parent=styles['Title'],fontSize=15,leading=18,alignment=TA_CENTER,textColor=colors.HexColor('#17365D'))); styles.add(ParagraphStyle(name='Small',parent=styles['BodyText'],fontSize=7,leading=14,alignment=TA_JUSTIFY)); story=[]
story += [Paragraph('Ejercicio 05 · Motor recomendador reproducible',styles['TitleCenter']),Paragraph('INF-8239 · Unidad 03 · Edwin Ramón José Nolasco',styles['Normal']),Spacer(1,4),Paragraph('Repositorio',styles['Heading2']),Paragraph('<link href="https://github.com/Vic-developers/Ejercicio-05-Motor-recomendador-reproducible" color="blue">github.com/Vic-developers/Ejercicio-05-Motor-recomendador-reproducible</link>',styles['BodyText'])]
story += [Paragraph('Datos y partición temporal',styles['Heading2']),Paragraph(f"MovieLens Latest Small: {audit['ratings']:,} ratings, {audit['movies']:,} películas, {audit['users']} usuarios; densidad {audit['density']:.2%}. SHA-256 ZIP {audit['sha256']}. Se retuvo el último evento por usuario; {audit['eligible_test_events']} eventos fueron elegibles y {audit['excluded_test_events']} se excluyeron por usuario o película sin soporte de entrenamiento. Tres semillas (17, 42, 73). Los datos no se incluyen en el repositorio.",styles['BodyText'])]
story += [Paragraph('Tabla principal de resultados',styles['Heading2'])]
labels={'popularity':'Popularidad','content':'Contenido','collaborative':'Colaborativo','hybrid_alpha_0.25':'Híbrido a=.25','hybrid_alpha_0.75':'Híbrido a=.75'}
rows=[['Config.','Método','RMSE','HR@10','Cob.','Seg.','Parám.']]
for _,r in main.iterrows(): rows.append([str(r.get('config','—')),labels.get(r.method,r.method),'—' if pd.isna(r.rmse) else f'{r.rmse:.3f}',f'{r.hit_rate_at_10:.3f}',f'{r.catalog_coverage:.1%}',f'{r.fit_seconds:.1f}',f"{int(r.model_parameters):,}"])
t=Table(rows,colWidths=[.75*inch,1.15*inch,.55*inch,.58*inch,.58*inch,.48*inch,.7*inch],repeatRows=1); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#17365D')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),6.7),('GRID',(0,0),(-1,-1),.3,colors.HexColor('#9EADBD')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#EDF2F7')]),('ALIGN',(2,1),(-1,-1),'RIGHT'),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('TOPPADDING',(0,0),(-1,-1),3),('BOTTOMPADDING',(0,0),(-1,-1),3)])); story += [t]
story += [Paragraph('Interpretación y decisión Pareto',styles['Heading2']),Paragraph('El baseline de popularidad alcanza HR@10=0.032 con 0.63% de cobertura, una señal de concentración. Contenido cubre 14.95% pero no recupera el ítem retenido. Entre híbridos, 20f/6e alpha=.75 obtiene HR=.020 y cobertura 18.2% con 6.8 s; 20f/12e alpha=.75 sube HR a .031, pero baja cobertura a 7.6% y tarda 13.6 s. Se elige 20f/6e alpha=.75 como compromiso de costo y exposición, manteniendo 20f/12e si prima el acierto y alpha=.25 si prima cobertura. Son alternativas Pareto eficientes; ninguna domina a las demás.',styles['BodyText'])]
prof=profiles[(profiles.config=='20f_6e') & profiles.method.isin(['collaborative','hybrid_alpha_0.75'])].groupby(['method','profile'],as_index=False).agg(users=('users','first'),hr=('hit_rate_at_10','mean'),cov=('catalog_coverage','mean'))
story += [PageBreak(),Paragraph('Perfiles y cold start',styles['Heading2'])]
pr=[['Modelo','Perfil','n','HR@10','Cobertura']]
for _,r in prof.iterrows(): pr.append([labels.get(r.method,r.method),'Corto' if r.profile=='historial_corto' else 'Amplio',str(int(r.users)),f"{r['hr']:.3f}",f"{r['cov']:.1%}"])
pt=Table(pr,colWidths=[1.2*inch,1.0*inch,.4*inch,.65*inch,.75*inch],repeatRows=1); pt.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#426782')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTSIZE',(0,0),(-1,-1),7),('GRID',(0,0),(-1,-1),.3,colors.HexColor('#9EADBD')),('ALIGN',(2,1),(-1,-1),'RIGHT')])); story += [pt,Paragraph('Historial corto: hasta 34 ratings (n=155); amplio: desde 167 (n=139). Prueba operativa: usuario nuevo con tres películas recibe 10 recomendaciones de contenido; usuario sin historial recibe 10 de popularidad suavizada. No se atribuye HR temporal a usuarios sin historial.',styles['BodyText'])]
story += [Paragraph('Errores, límites y reproducción',styles['Heading2']),Paragraph(f"Auditoría detallada de error: {len(errors)} filas para los 587 usuarios elegibles, con predicción retenida, acierto, rango y Top-5 por método (configuración 8f/6e, semilla 17). RMSE no implica mejor ranking. Existe sesgo de selección, no hay demografía y los géneros amplios pueden sobreespecializar. El notebook ejecutado, código, pruebas, CSV de resultados, README y requirements.txt están en el repositorio. MovieLens Latest Small es variable para desarrollo; se descarga localmente y no se redistribuye.",styles['BodyText'])]
story += [Paragraph('Uso responsable de IA y fuentes',styles['Heading2']),Paragraph('OpenAI Codex se usó como medio para detectar y corregir errores y revisar coherencia de ejecución. Prompts relevantes: revisar desempates del corte temporal, tipos de similitud coseno, índices del baseline y consistencia de métricas. Verificaciones: auditoría y hash, ejecución experimental, pruebas automatizadas y revisión de reportes; correcciones: desempate determinista, cohorte elegible explícita y normalización de tipos. El estudiante responde por el código y las conclusiones.',styles['Small']),Paragraph('Fuentes: GroupLens Research, MovieLens Latest Small README; Harper y Konstan (2015), The MovieLens Datasets: History and Context, DOI 10.1145/2827872.',styles['Small'])]
doc=SimpleDocTemplate(str(rep/'ejercicio_05_informe.pdf'),pagesize=letter,rightMargin=.48*inch,leftMargin=.48*inch,topMargin=.42*inch,bottomMargin=.42*inch,title='Ejercicio 05 - Motor recomendador reproducible',author='Edwin Ramón José Nolasco'); doc.build(story)
